/**
 * Hand-written from docs/design/01-api-spec.md (v0.2) plus the enum values of
 * 02-data-model.md. Contract-frozen in Phase 0: lanes do not edit this file.
 * Ids are 32-char hex strings, timestamps are RFC 3339 `Z` strings, dates are
 * `YYYY-MM-DD`, seconds in clips are numbers with 0.1 s precision.
 */

// ---------------------------------------------------------------- primitives

export type Id = string;
export type Timestamp = string;
export type DateString = string;

export type Situation =
  | "new_person"
  | "handling"
  | "leash_walk"
  | "other_dog"
  | "food_toys"
  | "alone_time"
  | "indoors_rest"
  | "children_cats";

export type Role = "staff" | "volunteer";
export type DogSex = "male" | "female" | "unknown";
export type DogSize = "small" | "medium" | "large";
export type DogStatus = "draft" | "published" | "adopted" | "deleted";
export type SessionStatus = "open" | "processing" | "review" | "failed";
export type SessionFailCode = "no_usable_clip" | "merge_failed";
export type ClipStatus = "uploaded" | "processing" | "ready" | "failed";
export type ClipStep = "transcode" | "transcribe" | "sample" | "draft";
/** Clip pipeline failure codes (02 section 3.3). Not HTTP errors. */
export type ClipFailCode =
  | "unsupported_file"
  | "too_long"
  | "transcode_failed"
  | "ai_failed"
  | "ai_invalid_output";
export type FactSource = "clip" | "narration" | "staff_note";
export type FactOrigin = "ai_unchanged" | "human_edited" | "human_added";
/** Creator-visible fact status. `deleted` facts are never returned. */
export type FactStatus = "draft" | "confirmed";
export type FlagCode = "banned_word" | "trait_claim" | "check_unavailable";
export type FlagSeverity = "warn" | "info";
export type FlagSource = "rules" | "model" | "system";
export type WordingCheck = "model" | "rules_only";
export type ChecklistMissing =
  "people_check" | "known_concerns" | "confirmed_fact";

// -------------------------------------------------------------------- errors

export type ErrorCode =
  | "malformed_request"
  | "upload_incomplete"
  | "unauthenticated"
  | "invalid_credentials"
  | "csrf_failed"
  | "forbidden_role"
  | "consent_required"
  | "not_own_session"
  | "staff_only_situation"
  | "not_found"
  | "invalid_state"
  | "clip_limit_reached"
  | "clip_not_ready"
  | "playback_required"
  | "flags_unacknowledged"
  | "publish_checklist_incomplete"
  | "file_too_large"
  | "unsupported_file_type"
  | "unsupported_media_type"
  | "validation_error"
  | "clip_too_long"
  | "evidence_out_of_range"
  | "question_too_short"
  | "rate_limited"
  | "internal_error"
  | "qa_cost_cap_reached"
  | "qa_unavailable"
  | "storage_unavailable";

export type ValidationProblem =
  | "required"
  | "too_short"
  | "too_long"
  | "invalid_value"
  | "duplicate"
  | "version_mismatch"
  | "evidence_required"
  | "range_not_completed";

export interface ValidationField {
  path: string;
  problem: ValidationProblem;
  limit?: number;
}

export type RateLimitScope = "ip" | "cookie" | "member" | "login";

/**
 * `details` is always an object; every key is optional because which keys
 * exist depends on the code (01 section 1.2).
 */
export interface ErrorDetails {
  /** validation_error */
  fields?: ValidationField[];
  /** playback_required */
  missing_evidence_ids?: Id[];
  /** publish_checklist_incomplete */
  missing?: ChecklistMissing[];
  /** file_too_large */
  max_bytes?: number;
  /** unsupported_file_type */
  allowed?: string[];
  reason?: "probe_timeout" | (string & {});
  /** clip_too_long */
  max_s?: number;
  duration_s?: number;
  /** rate_limited */
  scope?: RateLimitScope;
  /** internal_error */
  request_id?: string;
  [key: string]: unknown;
}

export interface ErrorEnvelope {
  error: {
    code: ErrorCode;
    message: string;
    details: ErrorDetails;
  };
}

// ------------------------------------------------------------ common objects

export interface Member {
  id: Id;
  email: string;
  display_name: string;
  role: Role;
  consented_at: Timestamp | null;
  consent_version: string | null;
}

export interface Contact {
  url: string | null;
  email: string | null;
  phone: string | null;
}

export interface Org {
  id: Id;
  name: string;
  country: string;
  location: string;
  contact: Contact;
}

export interface SituationCoverage {
  situation: Situation;
  label: string;
  covered: boolean;
  clip_count: number;
  filmed_s: number;
  confirmed_s: number;
}

export interface SituationRef {
  situation: Situation;
  label: string;
}

export interface Coverage {
  situations_total: number;
  situations_covered: number;
  /** Always all 8 entries in PRD order. */
  by_situation: SituationCoverage[];
  not_observed: SituationRef[];
}

/** Short form used by `GET /api/dogs` list rows. */
export interface CoverageSummary {
  situations_total: number;
  situations_covered: number;
}

export interface Dog {
  id: Id;
  name: string;
  sex: DogSex;
  age_estimate: string;
  size: DogSize;
  location: string | null;
  photo_url: string | null;
  status: DogStatus;
  public_slug: string | null;
  public_path: string | null;
  created_by: Id;
  created_at: Timestamp;
  published_at: Timestamp | null;
  adopted_at: Timestamp | null;
}

export interface Checklist {
  people_check: boolean;
  people_check_at: Timestamp | null;
  known_concerns: string | null;
  known_concerns_none: boolean;
  confirmed_fact_count: number;
  ready_to_publish: boolean;
  missing: ChecklistMissing[];
}

export interface ClipError {
  cause: string;
  retryable: boolean;
}

export interface Clip {
  id: Id;
  session_id: Id;
  ordinal: number;
  original_filename: string;
  original_size_bytes: number;
  duration_s: number;
  has_audio: boolean;
  status: ClipStatus;
  step: ClipStep | null;
  fail_code: ClipFailCode | null;
  error: ClipError | null;
  /** Set only when `status` is `ready`. */
  media_url: string | null;
  captions_url: string | null;
  created_at: Timestamp;
  ready_at: Timestamp | null;
}

export interface FactFlag {
  code: FlagCode;
  severity: FlagSeverity;
  source: FlagSource;
  detail: string;
}

/** Creator evidence item. URLs are used as served (D7). */
export interface Evidence {
  id: Id;
  clip_id: Id;
  start_s: number;
  end_s: number;
  played_by_me: boolean;
  media_url: string | null;
  captions_url: string | null;
}

export interface ClipLength {
  clip_count: number;
  seconds: number;
  label: string;
}

export interface FactConfirmation {
  by_member_id: Id;
  by_name: string;
  role: Role;
  at: Timestamp;
}

/** First failing confirm guard code (02 section 3.4), or null when allowed. */
export type BlockedReason = Extract<
  ErrorCode,
  | "invalid_state"
  | "consent_required"
  | "staff_only_situation"
  | "not_own_session"
  | "forbidden_role"
  | "playback_required"
  | "flags_unacknowledged"
  | "publish_checklist_incomplete"
  | "not_found"
>;

export interface Fact {
  id: Id;
  dog_id: Id;
  /** Null for a staff note with no clip. */
  session_id: Id | null;
  situation: Situation;
  behavior: string;
  source: FactSource;
  origin: FactOrigin;
  status: FactStatus;
  flags: FactFlag[];
  observed_on: DateString;
  evidence: Evidence[];
  clip_length: ClipLength;
  confirmed: FactConfirmation | null;
  created_by: Id | null;
  can_confirm: boolean;
  blocked_reason: BlockedReason | null;
}

export interface Session {
  id: Id;
  dog_id: Id;
  member_id: Id;
  owner_name: string;
  situations: Situation[];
  observed_on: DateString;
  status: SessionStatus;
  fail_code: SessionFailCode | null;
  created_at: Timestamp;
  submitted_at: Timestamp | null;
  review_ready_at: Timestamp | null;
}

// --------------------------------------------------------------- auth, member

export interface LoginRequest {
  email: string;
  password: string;
}

export interface Limits {
  max_clip_bytes: number;
  max_clip_s: number;
  max_clips_per_session: number;
  allowed_extensions: string[];
  wording_check: WordingCheck;
}

/** Body of `POST /api/auth/login`. */
export interface LoginResponse {
  member: Member;
  org: Org;
  csrf_token: string;
}

/** Body of `GET /api/me`. */
export interface MeResponse extends LoginResponse {
  limits: Limits;
}

export interface ConsentRequest {
  accepted: true;
  version: string;
}

export interface ConsentResponse {
  member: Member;
}

// ---------------------------------------------------------------------- dogs

export interface DogListItem {
  dog: Dog;
  coverage: CoverageSummary;
  counts: {
    draft_facts: number;
    confirmed_facts: number;
    sessions_in_review: number;
    clips: number;
  };
}

export interface DogListResponse {
  dogs: DogListItem[];
}

export interface CreateDogRequest {
  name: string;
  sex: DogSex;
  age_estimate: string;
  size: DogSize;
  location?: string | null;
}

export interface UpdateDogRequest {
  name?: string;
  sex?: DogSex;
  age_estimate?: string;
  size?: DogSize;
  /** `null` clears. */
  location?: string | null;
}

export interface DogResponse {
  dog: Dog;
}

export interface SessionSummary extends Session {
  clip_count: number;
  ready_clip_count: number;
  draft_fact_count: number;
}

export interface DogDetailResponse {
  dog: Dog;
  coverage: Coverage;
  checklist: Checklist;
  sessions: SessionSummary[];
  clips: Clip[];
  facts: Fact[];
}

export interface ChecklistRequest {
  people_check: boolean;
  known_concerns: string | null;
  known_concerns_none: boolean;
}

export interface ChecklistResponse {
  checklist: Checklist;
}

export interface PublishResponse {
  dog: Dog;
  public_url: string;
}

export interface DeleteDogResponse {
  dog_id: Id;
  status: "deleted";
  purge: "queued";
}

// ------------------------------------------------------------------ sessions

export interface CreateSessionRequest {
  situations: Situation[];
  /** Optional; defaults to today UTC on the server. */
  observed_on?: DateString;
  capture_rules_ack: boolean;
}

export interface SessionResponse {
  session: Session;
}

/** `GET /api/sessions/{id}?include=none`: no `facts` key at all. */
export interface SessionSummaryResponse {
  session: Session;
  clips: Clip[];
  progress: {
    clips_total: number;
    clips_ready: number;
    clips_failed: number;
  };
}

/** `GET /api/sessions/{id}` (default `include=facts`). */
export interface SessionDetailResponse extends SessionSummaryResponse {
  facts: Fact[];
}

/** What the backend publishes for the route: `facts` is absent for `include=none`. */
export type SessionDetailBody = SessionSummaryResponse & { facts?: Fact[] };

export type UploadWarning = "no_audio_track";

export interface ClipUploadResponse {
  clip: Clip;
  warnings: UploadWarning[];
}

export interface ClipResponse {
  clip: Clip;
}

export interface DeleteClipResponse {
  clip_id: Id;
  purge: "queued";
  facts_deleted: number;
  facts_demoted: number;
}

// --------------------------------------------------------------------- facts

export interface PlaybackCompleteRequest {
  evidence_id: Id;
  position_s: number;
  watched_s: number;
}

export interface PlaybackCompleteResponse {
  fact_id: Id;
  evidence_id: Id;
  completed_at: Timestamp;
  all_ranges_played: boolean;
}

export interface ConfirmFactRequest {
  acknowledge_flags?: boolean;
}

export interface FactResponse {
  fact: Fact;
}

export interface EvidenceInput {
  /** Present to keep an existing row whose range is unchanged. */
  id?: Id;
  clip_id: Id;
  start_s: number;
  end_s: number;
}

export interface UpdateFactRequest {
  situation?: Situation;
  behavior?: string;
  /** Full new list, 0 to 3 items. */
  evidence?: EvidenceInput[];
}

export interface AddFactRequest {
  situation: Situation;
  behavior: string;
  /** Omit or empty for a staff note. */
  evidence?: Omit<EvidenceInput, "id">[];
  /** Used only when there is no evidence. */
  observed_on?: DateString;
}

// -------------------------------------------------------------------- public

export interface PublicDog {
  slug: string;
  name: string;
  sex: DogSex;
  age_estimate: string;
  size: DogSize;
  /** Never null: the server falls back to the org location. */
  location: string;
  photo_url: string | null;
  published_at: Timestamp;
}

export interface PublicCoverage {
  situations_total: number;
  situations_covered: number;
  summary: string;
  by_situation: SituationCoverage[];
}

export interface KnownConcerns {
  none_known: boolean;
  /** Null when `none_known` is true. */
  text: string | null;
}

export interface FactNotice {
  code: "ask_shelter_in_person_meeting" | (string & {});
  text: string;
}

/** Public evidence item: no ids beyond the clip. */
export interface PublicEvidence {
  clip_id: Id;
  start_s: number;
  end_s: number;
  media_url: string;
  captions_url: string | null;
}

export interface PublicFact {
  id: Id;
  behavior: string;
  source: FactSource;
  source_label: string;
  observed_on: DateString;
  confirmed_by_label: string;
  clip_length: ClipLength;
  /** Set for every `children_cats` fact. */
  notice: FactNotice | null;
  /** Empty for a staff note. */
  evidence: PublicEvidence[];
}

export interface PublicFactGroup {
  situation: Situation;
  label: string;
  facts: PublicFact[];
}

export interface PublicProfile {
  banner_id: string;
  dog: PublicDog;
  org: { name: string; country: string };
  coverage: PublicCoverage;
  known_concerns: KnownConcerns;
  /** PRD order; situations without a confirmed fact are omitted. */
  facts_by_situation: PublicFactGroup[];
  not_observed: SituationRef[];
  contact: Contact;
  ask: {
    enabled: boolean;
    max_question_chars: number;
    limit_per_hour: number;
  };
}

export interface AskRequest {
  question: string;
}

export type AskOutcome = "answered" | "not_observed" | "health_redirect";

/** One answer line: a public fact plus its situation. `text` equals `fact.behavior`. */
export interface AnswerLine {
  fact_id: Id;
  text: string;
  situation: Situation;
  situation_label: string;
  source_label: string;
  observed_on: DateString;
  confirmed_by_label: string;
  clip_length: ClipLength;
  notice: FactNotice | null;
  evidence: PublicEvidence[];
}

export interface QaAnswer {
  outcome: AskOutcome;
  heading: string;
  /** Present for `not_observed` and `health_redirect`. */
  hint?: string;
  lines: AnswerLine[];
  cited_fact_ids: Id[];
  /** Present for `health_redirect`. */
  contact?: Contact;
  limits: { remaining_this_hour: number };
}

// --------------------------------------------------------------------- admin

export interface MetricsResponse {
  as_of: Timestamp;
  draft_acceptance: {
    confirmed_ai_unchanged: number;
    all_drafts: number;
    rate: number;
  };
  facts: {
    published_dogs: number;
    confirmed: number;
    with_clip_evidence: number;
    clip_evidence_share: number;
  };
  time: {
    median_session_to_review_s: number | null;
    median_dog_first_session_to_publish_s: number | null;
  };
  cost: {
    total_usd: number;
    per_dog_usd: { dog_id: Id; usd: number }[];
    qa_today_usd: number;
    qa_daily_cap_usd: number;
  };
  alerts: string[];
  purge_pending: Id[];
}

export interface HealthResponse {
  status: "ok";
}
